<?php
declare(strict_types=1);
session_start();
require dirname(__DIR__).'/config/config.php';
require_sign_in();
$role=$_SESSION['role']??'';$uid=(int)($_SESSION['user_id']??0);
if(!in_array($role,['system_admin','sub_admin','admin'],true)){http_response_code(403);exit('Your role cannot analyze schools.');}
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){http_response_code(400);exit('Choose a school.');}
$db=db();$sql='SELECT s.id,s.name,s.location,s.status FROM schools s WHERE s.id=?';$params=[$id];if($role==='admin'){$sql.=' AND EXISTS(SELECT 1 FROM school_memberships m WHERE m.school_id=s.id AND m.user_id=?)';$params[]=$uid;}$q=$db->prepare($sql);$q->execute($params);$school=$q->fetch();if(!$school){http_response_code(404);exit('School not found in your access.');}
$count=static function(string $sql,array $params)use($db):int{$q=$db->prepare($sql);$q->execute($params);return(int)$q->fetchColumn();};
$pupils=$count("SELECT COUNT(*) FROM pupils WHERE school_id=? AND status='active'",[$id]);$classes=$count('SELECT COUNT(*) FROM school_classes WHERE school_id=?',[$id]);$streams=$count('SELECT COUNT(*) FROM school_streams st JOIN school_classes c ON c.id=st.class_id WHERE c.school_id=?',[$id]);$subjects=$count('SELECT COUNT(*) FROM school_class_subjects sj JOIN school_classes c ON c.id=sj.class_id WHERE c.school_id=?',[$id]);$teachers=$count('SELECT COUNT(DISTINCT user_id) FROM teacher_assignments WHERE school_id=? AND active=1',[$id]);$exams=$count('SELECT COUNT(*) FROM school_exams WHERE school_id=?',[$id]);$resultRows=$count('SELECT COUNT(*) FROM pupil_results WHERE school_id=?',[$id]);$averageQ=$db->prepare('SELECT ROUND(AVG(score/max_score*100),1) FROM pupil_results WHERE school_id=? AND max_score>0');$averageQ->execute([$id]);$average=$averageQ->fetchColumn();
$q=$db->prepare("SELECT class_level,COUNT(*) pupil_count FROM pupils WHERE school_id=? AND status='active' GROUP BY class_level ORDER BY class_level");$q->execute([$id]);$pupilBreakdown=$q->fetchAll();$q=$db->prepare('SELECT exam_name,academic_year,COUNT(*) result_count,ROUND(AVG(score/max_score*100),1) average_percent FROM pupil_results WHERE school_id=? AND max_score>0 GROUP BY exam_name,academic_year ORDER BY academic_year DESC,exam_name DESC');$q->execute([$id]);$examBreakdown=$q->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($school['name'])?> · School analysis</title><link rel="stylesheet" href="assets/app.css"></head><body><div class="app-shell"><aside class="sidebar"><a class="brand" href="index.php"><span class="brand-mark">S</span><span>shule<span class="brand-lite">lite</span></span></a><div class="workspace-label">WORKSPACE</div><nav class="side-nav" aria-label="Main navigation"><a class="nav-item" href="index.php">⌂ &nbsp;Overview</a><a class="nav-item active" href="schools.php">▦ &nbsp;Schools</a><a class="nav-item" href="team.php">♧ &nbsp;People</a></nav><div class="sidebar-bottom"><a class="nav-item" href="logout.php">↪ &nbsp;Sign out</a></div></aside><main class="main-area"><header class="topbar"><div class="crumb">Workspace <span>/</span><a href="schools.php">Schools</a><span>/</span>Analyze</div><div class="top-actions"><span class="role-chip"><?=e(str_replace('_',' ',$role))?></span><div class="user-name"><?=e($_SESSION['name']??'')?></div></div></header><div class="page-content"><section class="setup-hero"><div><div class="eyebrow">SCHOOL ANALYSIS</div><h1><?=e($school['name'])?></h1><p class="muted"><?=e($school['location']?:'Location not recorded')?> · <?=e(ucfirst($school['status']))?></p></div><div class="academic-row-actions"><a class="button" href="school_view.php?id=<?=$id?>">View school</a><a class="button" href="schools.php">Back to schools</a></div></section><section class="metric-grid"><article class="metric-card"><div class="metric-label">ACTIVE PUPILS</div><div class="metric-value"><?=number_format($pupils)?></div><div class="metric-note">Current enrollment</div></article><article class="metric-card"><div class="metric-label">CLASSES</div><div class="metric-value"><?=$classes?></div><div class="metric-note"><?=number_format($streams)?> streams · <?=number_format($subjects)?> subjects</div></article><article class="metric-card"><div class="metric-label">TEACHERS</div><div class="metric-value"><?=$teachers?></div><div class="metric-note">With active assignments</div></article><article class="metric-card"><div class="metric-label">EXAMS</div><div class="metric-value"><?=$exams?></div><div class="metric-note"><?=number_format($resultRows)?> recorded result rows</div></article><article class="metric-card"><div class="metric-label">AVERAGE SCORE</div><div class="metric-value"><?=$average===null?'—':e((string)$average.'%')?></div><div class="metric-note">Mean percentage across recorded results</div></article></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">ENROLLMENT</div><h2>Active pupils by class</h2></div></div><?php if($pupilBreakdown):?><div class="table-wrap"><table><thead><tr><th>Class</th><th>Active pupils</th><th>Share of school</th></tr></thead><tbody><?php foreach($pupilBreakdown as $row):?><tr><th><?=e($row['class_level'])?></th><td><?=number_format((int)$row['pupil_count'])?></td><td><?=$pupils?number_format((int)$row['pupil_count']/$pupils*100,1):'0.0'?>%</td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h3>No active pupils</h3><p>Enrollment analysis will appear when pupils are registered.</p></div><?php endif;?></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">ASSESSMENTS</div><h2>Exam results</h2></div></div><?php if($examBreakdown):?><div class="table-wrap"><table><thead><tr><th>Exam</th><th>Result rows</th><th>Average score</th></tr></thead><tbody><?php foreach($examBreakdown as $row):?><tr><th><?=e($row['exam_name'].' · '.$row['academic_year'])?></th><td><?=number_format((int)$row['result_count'])?></td><td><?=e((string)$row['average_percent'])?>%</td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h3>No results recorded</h3><p>Exam analysis will appear when results are entered.</p></div><?php endif;?></section></div></main></div></body></html>
